#include "../ui.h"

lv_obj_t * ui_Muyu = NULL;
lv_obj_t * ui_MuyuPanel = NULL;
lv_obj_t * ui_MuyuImage = NULL;

static void ui_muyu_wait_release(void)
{
    lv_indev_t *indev = lv_indev_get_act();

    if (indev != NULL)
        lv_indev_wait_release(indev);
}

void ui_Muyu_return(void)
{
    ui_muyu_wait_release();
    ui_AppGrid_open();
}

void ui_Muyu_open_from_app_grid(void)
{
    ui_muyu_wait_release();
    _ui_screen_change(&ui_Muyu, LV_SCR_LOAD_ANIM_MOVE_LEFT, 180, 0,
                      &ui_Muyu_screen_init);
}

// event functions
void ui_event_Muyu(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_indev_t *indev = lv_indev_get_act();

    if (event_code == LV_EVENT_GESTURE && indev != NULL &&
        lv_indev_get_gesture_dir(indev) == LV_DIR_TOP)
        ui_Muyu_return();
}

void ui_event_MuyuPanel(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_indev_t *indev = lv_indev_get_act();

    if (event_code == LV_EVENT_GESTURE && indev != NULL &&
        lv_indev_get_gesture_dir(indev) == LV_DIR_LEFT)
        ui_Muyu_return();
}

void ui_event_MuyuImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_CLICKED) {
        on_muyu_pressed(e);
        ui_muyu_press_animation(ui_MuyuImage, 0);
    }
}

// build functions

