    ui_MuyuPanel = lv_obj_create(ui_Muyu);
    lv_obj_set_width(ui_MuyuPanel, 390);
    lv_obj_set_height(ui_MuyuPanel, 450);
    lv_obj_set_align(ui_MuyuPanel, LV_ALIGN_CENTER);
    lv_obj_clear_flag(ui_MuyuPanel, LV_OBJ_FLAG_SCROLLABLE);      /// Flags
    lv_obj_add_flag(ui_MuyuPanel, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_set_style_radius(ui_MuyuPanel, 45, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(ui_MuyuPanel, lv_color_hex(0x000000), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(ui_MuyuPanel, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(ui_MuyuPanel, 0, LV_PART_MAIN | LV_STATE_DEFAULT);

    ui_MuyuImage = lv_img_create(ui_MuyuPanel);
    lv_img_set_src(ui_MuyuImage, &ui_img_fish4_png);
    lv_obj_set_width(ui_MuyuImage, LV_SIZE_CONTENT);   /// 1
    lv_obj_set_height(ui_MuyuImage, LV_SIZE_CONTENT);    /// 1
    lv_obj_set_x(ui_MuyuImage, -1);
    lv_obj_set_y(ui_MuyuImage, 21);
    lv_obj_set_align(ui_MuyuImage, LV_ALIGN_CENTER);
    lv_obj_add_flag(ui_MuyuImage, LV_OBJ_FLAG_CLICKABLE |
                    LV_OBJ_FLAG_ADV_HITTEST | LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_clear_flag(ui_MuyuImage, LV_OBJ_FLAG_SCROLLABLE);      /// Flags

    lv_obj_add_event_cb(ui_MuyuImage, ui_event_MuyuImage, LV_EVENT_ALL, NULL);
    lv_obj_add_event_cb(ui_MuyuPanel, ui_event_MuyuPanel, LV_EVENT_ALL, NULL);
    lv_obj_add_event_cb(ui_Muyu, ui_event_Muyu, LV_EVENT_ALL, NULL);

