void ui_Muyu_screen_destroy(void)
{
    if(ui_Muyu) lv_obj_del(ui_Muyu);

    // NULL screen variables
    ui_Muyu = NULL;
    ui_MuyuPanel = NULL;
    ui_MuyuImage = NULL;

}
